// ─── INTERACTIVE "CHECK THE NUMBERS" CALCULATORS (6 LANGUAGES) ─────────
(function() {
  function fmtINR(n) {
    const num = Math.round(Number(n) || 0);
    const sign = num < 0 ? "-" : "";
    return sign + "₹" + Math.abs(num).toLocaleString("en-IN");
  }

  // Compute true IRR for Endowment/ULIP cashflows:
  // Pay `premium` at t = 0 .. payYears-1, receive `payout` at t = matYears
  function computeEndowmentXIRR(premium, payYears, matYears, payout) {
    if (premium <= 0 || payYears <= 0 || matYears <= 0 || payout <= 0) return 0;
    let low = -0.5, high = 0.5;
    for (let iter = 0; iter < 60; iter++) {
      const mid = (low + high) / 2;
      let npv = 0;
      for (let t = 0; t < payYears; t++) {
        npv -= premium / Math.pow(1 + mid, t);
      }
      npv += payout / Math.pow(1 + mid, matYears);
      if (npv > 0) low = mid;
      else high = mid;
    }
    return ((low + high) / 2) * 100;
  }

  // Compute Index Fund corpus at 12% CAGR for same cashflows
  function computeIndexCorpus(premium, payYears, matYears, rate) {
    let total = 0;
    for (let t = 0; t < payYears; t++) {
      const yearsCompounded = Math.max(0, matYears - t);
      total += premium * Math.pow(1 + rate, yearsCompounded);
    }
    return total;
  }

  window.I18N.calculators = {
    "direct-equity": {
      inputs: [
        { key: "amount", min: 1000, max: 100000000, step: 10000, defaultVal: 100000,
          label: { en: "Invested (₹)", kn: "ಹೂಡಿಕೆ ಮೊತ್ತ (₹)", mr: "गुंतवणूक रक्कम (₹)", te: "పెట్టుబడి (₹)", ta: "முதலீடு (₹)", hi: "निवेश राशि (₹)" } },
        { key: "gain", min: 1000, max: 50000000, step: 5000, defaultVal: 50000,
          label: { en: "Profit Made (₹)", kn: "ಬಂದ ಲಾಭ (₹)", mr: "झालेला नफा (₹)", te: "వచ్చిన లాభం (₹)", ta: "கிடைத்த லாபம் (₹)", hi: "हुआ मुनाफा (₹)" } },
        { key: "months", min: 1, max: 120, step: 1, defaultVal: 8,
          label: { en: "Held For (Months)", kn: "ಅವಧಿ (ತಿಂಗಳು)", mr: "कालावधी (महिने)", te: "కాలపరిమితి (నెలలు)", ta: "காலம் (மாதங்கள்)", hi: "अवधि (महीने)" } }
      ],
      compute: function(v, lang) {
        const gain = Math.max(0, v.gain);
        const stcgTax = Math.round(gain * 0.208); // 20% + 4% cess
        const ltcgTaxable = Math.max(0, gain - 125000);
        const ltcgTax = Math.round(ltcgTaxable * 0.13); // 12.5% + 4% cess
        const isShort = v.months <= 12;
        const activeTax = isShort ? stcgTax : ltcgTax;
        const savedIfWait = Math.max(0, stcgTax - ltcgTax);
        const msgs = {
          en: isShort
            ? `Selling at ${v.months} months triggers 20% STCG (+4% cess) = ${fmtINR(stcgTax)} tax. Waiting past 12 months uses the ₹1.25L LTCG exemption—tax drops to ${fmtINR(ltcgTax)} (you save ${fmtINR(savedIfWait)}).`
            : `Held for ${v.months} months (>12m): first ₹1,25,000 gain per year is 0% tax. Your LTCG tax is ${fmtINR(ltcgTax)} instead of ${fmtINR(stcgTax)} short-term tax (saving ${fmtINR(savedIfWait)}).`,
          kn: isShort
            ? `${v.months} ತಿಂಗಳಲ್ಲಿ ಮಾರಾಟ ಮಾಡಿದರೆ 20% STCG (+4% ಸೆಸ್) = ${fmtINR(stcgTax)} ತೆರಿಗೆ ಕಟ್ಟಬೇಕು. 12 ತಿಂಗಳ ನಂತರ ಮಾರಿದರೆ ₹1.25L ವಿನಾಯಿತಿ ಸಿಕ್ಕಿ ತೆರಿಗೆ ${fmtINR(ltcgTax)} ಆಗುತ್ತದೆ (ನಿಮ್ಮ ಉಳಿತಾಯ ${fmtINR(savedIfWait)}).`
            : `${v.months} ತಿಂಗಳು (>12 ತಿಂಗಳು) ಇಟ್ಟಿದ್ದರಿಂದ ವರ್ಷಕ್ಕೆ ₹1,25,000 ವರೆಗಿನ ಲಾಭಕ್ಕೆ 0% ತೆರಿಗೆ. ನಿಮ್ಮ LTCG ತೆರಿಗೆ ಕೇವಲ ${fmtINR(ltcgTax)} (STCG ${fmtINR(stcgTax)} ಬದಲಿಗೆ ${fmtINR(savedIfWait)} ಉಳಿತಾಯ).`,
          mr: isShort
            ? `${v.months} महिन्यांत विकल्यास २०% STCG (+४% सेस) = ${fmtINR(stcgTax)} कर लागतो. १२ महिन्यांनंतर विकल्यास ₹१.२५ लाखांच्या सवलतीमुळे कर ${fmtINR(ltcgTax)} होतो (तुमची बचत ${fmtINR(savedIfWait)}).`
            : `${v.months} महिने (>१२ महिने) ठेवल्यामुळे ₹१,२५,००० पर्यंतच्या नफ्यावर ०% कर. तुमचा LTCG कर फक्त ${fmtINR(ltcgTax)} होतो (${fmtINR(savedIfWait)} कराची बचत).`,
          te: isShort
            ? `${v.months} నెలల్లో అమ్మితే 20% STCG (+4% సెస్) = ${fmtINR(stcgTax)} పన్ను పడుతుంది. 12 నెలల తర్వాత అమ్మితే ₹1.25L మినహాయింపుతో పన్ను ${fmtINR(ltcgTax)} మాత్రమే (మీకు ${fmtINR(savedIfWait)} ఆదా).`
            : `${v.months} నెలలు (>12 నెలలు) ఉంచినందున ₹1,25,000 వరకు లాభంపై 0% పన్ను. మీ LTCG పన్ను కేవలం ${fmtINR(ltcgTax)} మాత్రమే (${fmtINR(savedIfWait)} పన్ను ఆదా).`,
          ta: isShort
            ? `${v.months} மாதத்தில் விற்றால் 20% STCG (+4% செஸ்) = ${fmtINR(stcgTax)} வரி. 12 மாதங்களுக்குப் பின் விற்றால் ₹1.25L விலக்கு கிடைத்து வரி ${fmtINR(ltcgTax)} ஆகக் குறையும் (உங்கள் சேமிப்பு ${fmtINR(savedIfWait)}).`
            : `${v.months} மாதங்கள் (>12 மாதம்) வைத்திருந்ததால் ₹1,25,000 வரையிலான லாபத்திற்கு 0% வரி. உங்கள் LTCG வரி ${fmtINR(ltcgTax)} மட்டுமே (${fmtINR(savedIfWait)} வரி சேமிப்பு).`,
          hi: isShort
            ? `${v.months} महीने में बेचने पर 20% STCG (+4% सेस) = ${fmtINR(stcgTax)} टैक्स लगेगा। 12 महीने बाद बेचने पर ₹1.25L छूट के कारण टैक्स घटकर ${fmtINR(ltcgTax)} रह जाता है (आपकी बचत: ${fmtINR(savedIfWait)})।`
            : `${v.months} महीने (>12 महीने) रखने पर सालाना ₹1,25,000 तक के मुनाफे पर 0% टैक्स है। आपका LTCG टैक्स केवल ${fmtINR(ltcgTax)} होगा (${fmtINR(savedIfWait)} की टैक्स बचत)।`
        };
        return msgs[lang] || msgs.en;
      }
    },

    "equity-mf": {
      inputs: [
        { key: "amount", min: 5000, max: 100000000, step: 10000, defaultVal: 100000,
          label: { en: "Investment (₹)", kn: "ಹೂಡಿಕೆ ಮೊತ್ತ (₹)", mr: "गुंतवणूक (₹)", te: "పెట్టుబడి (₹)", ta: "முதலீடு (₹)", hi: "निवेश राशि (₹)" } },
        { key: "years", min: 1, max: 40, step: 1, defaultVal: 20,
          label: { en: "Period (Years)", kn: "ಅವಧಿ (ವರ್ಷಗಳು)", mr: "कालावधी (वर्षे)", te: "కాలం (ఏళ్లు)", ta: "காலம் (ஆண்டுகள்)", hi: "अवधि (वर्ष)" } },
        { key: "comm", min: 0.2, max: 2.0, step: 0.1, defaultVal: 1.0,
          label: { en: "Regular Commission (%)", kn: "ಏಜೆಂಟ್ ಕಮಿಷನ್ (%)", mr: "एजंट कमिशन (%)", te: "ఏజెంట్ కమీషన్ (%)", ta: "ஏஜெண்ட் கமிஷன் (%)", hi: "एजेंट कमीशन (%)" } }
      ],
      compute: function(v, lang) {
        const directRate = 0.118; // 12% gross - 0.2% Direct TER
        const regRate = Math.max(0.01, directRate - (v.comm / 100));
        const directCorpus = v.amount * Math.pow(1 + directRate, v.years);
        const regCorpus = v.amount * Math.pow(1 + regRate, v.years);
        const lost = Math.max(0, directCorpus - regCorpus);
        const pctLost = directCorpus > 0 ? ((lost / directCorpus) * 100).toFixed(0) : 0;
        const msgs = {
          en: `At 12% gross growth over ${v.years} yrs: a Direct Plan grows to ${fmtINR(directCorpus)}, while a Regular Plan (${v.comm}% commission trail) grows to ${fmtINR(regCorpus)}—you lose ${fmtINR(lost)} (${pctLost}% of your wealth) silently to middlemen.`,
          kn: `12% ಬೆಳವಣಿಗೆಯಲ್ಲಿ ${v.years} ವರ್ಷಗಳಲ್ಲಿ: Direct ಪ್ಲಾನ್ ${fmtINR(directCorpus)} ಆದರೆ, Regular ಪ್ಲಾನ್ (${v.comm}% ಕಮಿಷನ್) ${fmtINR(regCorpus)} ಮಾತ್ರ ಆಗುತ್ತದೆ—ನೀವು ${fmtINR(lost)} (${pctLost}% ಸಂಪತ್ತು) ಏಜೆಂಟ್ ಕಮಿಷನ್‌ಗೆ ಕಳೆದುಕೊಳ್ಳುತ್ತೀರಿ.`,
          mr: `१२% वाढीने ${v.years} वर्षांत: Direct प्लॅनमध्ये ${fmtINR(directCorpus)} होतात, तर Regular प्लॅनमध्ये (${v.comm}% कमिशन) फक्त ${fmtINR(regCorpus)} मिळतात—तुमचे ${fmtINR(lost)} (${pctLost}% संपत्ती) एजंट कमिशनमध्ये जातात.`,
          te: `12% వృద్ధితో ${v.years} ఏళ్లలో: Direct ప్లాన్ ${fmtINR(directCorpus)} అవుతుంది, కానీ Regular ప్లాన్ (${v.comm}% కమీషన్) ${fmtINR(regCorpus)} మాత్రమే అవుతుంది—మీరు ${fmtINR(lost)} (${pctLost}% సంపద) కమీషన్లకే నష్టపోతారు.`,
          ta: `12% வளர்ச்சியில் ${v.years} ஆண்டுகளில்: Direct திட்டம் ${fmtINR(directCorpus)} ஆக உயரும், ஆனால் Regular திட்டம் (${v.comm}% கமிஷன்) ${fmtINR(regCorpus)} மட்டுமே ஆகும்—நீங்கள் ${fmtINR(lost)} (${pctLost}% செல்வம்) கமிஷனில் இழக்கிறீர்கள்.`,
          hi: `12% सालाना वृद्धि पर ${v.years} वर्षों में: Direct प्लान बढ़कर ${fmtINR(directCorpus)} बनता है, जबकि Regular प्लान (${v.comm}% कमीशन) सिर्फ ${fmtINR(regCorpus)} रह जाता है—आप ${fmtINR(lost)} (${pctLost}% संपत्ति) कमीशन में गंवा देते हैं।`
        };
        return msgs[lang] || msgs.en;
      }
    },

    "debt-mf": {
      inputs: [
        { key: "amount", min: 5000, max: 100000000, step: 10000, defaultVal: 100000,
          label: { en: "Investment (₹)", kn: "ಹೂಡಿಕೆ ಮೊತ್ತ (₹)", mr: "गुंतवणूक (₹)", te: "పెట్టుబడి (₹)", ta: "முதலீடு (₹)", hi: "निवेश राशि (₹)" } },
        { key: "years", min: 1, max: 20, step: 1, defaultVal: 5,
          label: { en: "Period (Years)", kn: "ಅವಧಿ (ವರ್ಷಗಳು)", mr: "कालावधी (वर्षे)", te: "కాలం (ఏళ్లు)", ta: "காலம் (ஆண்டுகள்)", hi: "अवधि (वर्ष)" } },
        { key: "slab", min: 0, max: 30, step: 5, defaultVal: 30,
          label: { en: "Tax Slab (%)", kn: "ತೆರಿಗೆ ಸ್ಲ್ಯಾಬ್ (%)", mr: "टॅक्स स्लॅब (%)", te: "ట్యాక్స్ స్లాబ్ (%)", ta: "வரி வரம்பு (%)", hi: "टैक्स स्लैब (%)" } }
      ],
      compute: function(v, lang) {
        const effTax = (v.slab * 1.04) / 100;
        const r = 0.07;
        // Debt MF: compounds at 7%, taxed once at exit
        const grossCorpus = v.amount * Math.pow(1 + r, v.years);
        const debtNet = v.amount + (grossCorpus - v.amount) * (1 - effTax);
        // Bank FD: taxed every year at effTax
        const fdNet = v.amount * Math.pow(1 + r * (1 - effTax), v.years);
        const extra = Math.max(0, debtNet - fdNet);
        const defaultLoss = Math.round(grossCorpus * 0.08);
        const msgs = {
          en: `At 7% over ${v.years} yrs (${v.slab}% slab): Debt MF post-tax value is ${fmtINR(debtNet)} vs ${fmtINR(fdNet)} in a Bank FD (${fmtINR(extra)} extra via tax deferral). But if 1 bond in a Credit Risk fund defaults (8% hit), you lose ${fmtINR(defaultLoss)} overnight.`,
          kn: `7% ಬಡ್ಡಿಯಲ್ಲಿ ${v.years} ವರ್ಷಕ್ಕೆ (${v.slab}% ಸ್ಲ್ಯಾಬ್): ಡೆಟ್ ಫಂಡ್ ನಿವ್ವಳ ಮೊತ್ತ ${fmtINR(debtNet)} vs ಬ್ಯಾಂಕ್ FD ${fmtINR(fdNet)} (${fmtINR(extra)} ಹೆಚ್ಚುವರಿ ಲಾಭ). ಆದರೆ ಕ್ರೆಡಿಟ್ ರಿಸ್ಕ್ ಫಂಡ್‌ನಲ್ಲಿ 1 ಕಂಪನಿ ಸುಸ್ತಿದಾರನಾದರೂ ರಾತ್ರೋರಾತ್ರಿ ${fmtINR(defaultLoss)} ನಷ್ಟವಾಗುತ್ತದೆ.`,
          mr: `७% दराने ${v.years} वर्षांत (${v.slab}% स्लॅब): डेट फंडात करानंतर ${fmtINR(debtNet)} मिळतात तर बँक FD मध्ये ${fmtINR(fdNet)} (${fmtINR(extra)} अधिक फायदा). पण Credit Risk फंडातील १ बॉण्ड बुडाल्यास एका रात्रीत ${fmtINR(defaultLoss)} नुकसान होते.`,
          te: `7% రాబడితో ${v.years} ఏళ్లలో (${v.slab}% స్లాబ్): డెట్ ఫండ్ పన్ను తర్వాత విలువ ${fmtINR(debtNet)} vs బ్యాంకు FD ${fmtINR(fdNet)} (${fmtINR(extra)} అదనపు లాభం). కానీ Credit Risk ఫండ్‌లో 1 బాండ్ డిఫాల్ట్ అయినా ఒక్క రాత్రిలో ${fmtINR(defaultLoss)} నష్టపోతారు.`,
          ta: `7% வட்டியில் ${v.years} ஆண்டுகளில் (${v.slab}% வரி): டெட் ஃபண்ட் வரிக்குப் பின் ${fmtINR(debtNet)} vs வங்கி FD ${fmtINR(fdNet)} (${fmtINR(extra)} கூடுதல் லாபம்). ஆனால் Credit Risk ஃபண்டில் 1 பாண்ட் மூழ்கினாலும் ஒரே இரவில் ${fmtINR(defaultLoss)} இழப்பு ஏற்படும்.`,
          hi: `7% दर पर ${v.years} वर्षों में (${v.slab}% स्लैब): डेट फंड का टैक्स के बाद मूल्य ${fmtINR(debtNet)} होगा बनाम बैंक FD में ${fmtINR(fdNet)} (${fmtINR(extra)} का अतिरिक्त लाभ)। लेकिन Credit Risk फंड में 1 बॉन्ड डिफ़ॉल्ट होने पर रातों-रात ${fmtINR(defaultLoss)} डूब सकते हैं।`
        };
        return msgs[lang] || msgs.en;
      }
    },

    "etf": {
      inputs: [
        { key: "amount", min: 1000, max: 100000000, step: 10000, defaultVal: 100000,
          label: { en: "Order Amount (₹)", kn: "ಆರ್ಡರ್ ಮೊತ್ತ (₹)", mr: "खरेदी रक्कम (₹)", te: "కొనుగోలు మొత్తం (₹)", ta: "வாங்கும் தொகை (₹)", hi: "खरीद राशि (₹)" } },
        { key: "prem", min: 0, max: 20, step: 0.5, defaultVal: 5.0,
          label: { en: "Price Premium over iNAV (%)", kn: "iNAV ಗಿಂತ ಹೆಚ್ಚುವರಿ ಬೆಲೆ (%)", mr: "iNAV पेक्षा जास्त भाव (%)", te: "iNAV కంటే అదనపు ధర (%)", ta: "iNAV விட கூடுதல் விலை (%)", hi: "iNAV से ऊपर प्रीमियम (%)" } }
      ],
      compute: function(v, lang) {
        const trueVal = v.amount / (1 + v.prem / 100);
        const overpaid = Math.max(0, v.amount - trueVal);
        const msgs = {
          en: `Buying ${fmtINR(v.amount)} via Market Order when the ETF trades at a ${v.prem}% premium to iNAV gives you only ${fmtINR(trueVal)} of real underlying asset—you lose ${fmtINR(overpaid)} on Day 1. Always check iNAV and place a Limit Order.`,
          kn: `ETF ಬೆಲೆಯು iNAV ಗಿಂತ ${v.prem}% ಹೆಚ್ಚಿರುವಾಗ ${fmtINR(v.amount)} Market Order ಹಾಕಿದರೆ ನಿಮಗೆ ಸಿಗುವ ನಿಜವಾದ ಆಸ್ತಿ ಮೌಲ್ಯ ಕೇವಲ ${fmtINR(trueVal)}—ಮೊದಲ ದಿನವೇ ${fmtINR(overpaid)} ನಷ್ಟವಾಗುತ್ತದೆ. ಯಾವಾಗಲೂ Limit Order ಬಳಸಿ.`,
          mr: `ETF चा भाव iNAV पेक्षा ${v.prem}% जास्त असताना ${fmtINR(v.amount)} चा Market Order टाकल्यास तुम्हाला प्रत्यक्षात फक्त ${fmtINR(trueVal)} चीच मालमत्ता मिळते—पहिल्याच दिवशी ${fmtINR(overpaid)} नुकसान होते. नेहमी Limit Order वापरा.`,
          te: `ETF ధర iNAV కంటే ${v.prem}% ఎక్కువగా ఉన్నప్పుడు ${fmtINR(v.amount)} Market Order పెడితే మీకు లభించే నిజమైన ఆస్తి విలువ ${fmtINR(trueVal)} మాత్రమే—మొదటి రోజే ${fmtINR(overpaid)} నష్టపోతారు. ఎల్లప్పుడూ Limit Order పెట్టండి.`,
          ta: `ETF விலை iNAV-ஐ விட ${v.prem}% அதிகமாக இருக்கும்போது ${fmtINR(v.amount)} Market Order போட்டால் உங்களுக்குக் கிடைக்கும் உண்மையான சொத்து மதிப்பு ${fmtINR(trueVal)} மட்டுமே—முதல் நாளே ${fmtINR(overpaid)} இழப்பு. எப்போதும் Limit Order போடுங்கள்.`,
          hi: `जब ETF अपने iNAV से ${v.prem}% प्रीमियम पर हो, तब ${fmtINR(v.amount)} का Market Order लगाने पर आपको वास्तव में सिर्फ ${fmtINR(trueVal)} की संपत्ति मिलती है—पहले ही दिन ${fmtINR(overpaid)} का नुकसान। हमेशा Limit Order लगाएं।`
        };
        return msgs[lang] || msgs.en;
      }
    },

    "fd": {
      inputs: [
        { key: "amount", min: 5000, max: 100000000, step: 25000, defaultVal: 100000,
          label: { en: "FD Amount (₹)", kn: "FD ಮೊತ್ತ (₹)", mr: "FD रक्कम (₹)", te: "FD మొత్తం (₹)", ta: "FD தொகை (₹)", hi: "FD राशि (₹)" } },
        { key: "rate", min: 4, max: 10, step: 0.25, defaultVal: 7.0,
          label: { en: "FD Interest Rate (%)", kn: "FD ಬಡ್ಡಿ ದರ (%)", mr: "FD व्याजदर (%)", te: "FD వడ్డీ రేటు (%)", ta: "FD வட்டி (%)", hi: "FD ब्याज दर (%)" } },
        { key: "slab", min: 0, max: 30, step: 5, defaultVal: 30,
          label: { en: "Your Tax Slab (%)", kn: "ನಿಮ್ಮ ತೆರಿಗೆ ಸ್ಲ್ಯಾಬ್ (%)", mr: "तुमचा टॅक्स स्लॅब (%)", te: "మీ ట్యాక్స్ స్లాబ్ (%)", ta: "உங்கள் வரி வரம்பு (%)", hi: "आपका टैक्स स्लैब (%)" } }
      ],
      compute: function(v, lang) {
        const grossInt = v.amount * (v.rate / 100);
        const effTaxRate = v.slab > 0 ? (v.slab * 1.04) / 100 : 0;
        const taxPaid = grossInt * effTaxRate;
        const netInt = grossInt - taxPaid;
        const netYield = (v.rate * (1 - effTaxRate)).toFixed(2);
        const uninsured = Math.max(0, v.amount - 500000);
        const insNote = {
          en: uninsured > 0 ? ` Warning: ${fmtINR(uninsured)} exceeds the ₹5L RBI DICGC insurance cap.` : "",
          kn: uninsured > 0 ? ` ಎಚ್ಚರಿಕೆ: ${fmtINR(uninsured)} ಮೊತ್ತಕ್ಕೆ RBI ನ ₹5L DICGC ವಿಮಾ ರಕ್ಷಣೆ ಇರುವುದಿಲ್ಲ.` : "",
          mr: uninsured > 0 ? ` इशारा: ${fmtINR(uninsured)} रकमेला RBI चे ₹5L DICGC विमा संरक्षण नाही.` : "",
          te: uninsured > 0 ? ` హెచ్చరిక: ${fmtINR(uninsured)} మొత్తానికి RBI ₹5L DICGC బీమా రక్షణ ఉండదు.` : "",
          ta: uninsured > 0 ? ` எச்சரிக்கை: ${fmtINR(uninsured)} தொகைக்கு RBI-இன் ₹5L DICGC காப்பீடு கிடையாது.` : "",
          hi: uninsured > 0 ? ` चेतावनी: ${fmtINR(uninsured)} की राशि RBI की ₹5L DICGC बीमा सीमा से बाहर है।` : ""
        };
        const msgs = {
          en: `Gross interest is ${fmtINR(grossInt)}/yr, but at the ${v.slab}% slab you pay ${fmtINR(taxPaid)} in tax—leaving ${fmtINR(netInt)} (${netYield}% post-tax return, trailing ~6% real inflation).${insNote.en}`,
          kn: `ಒಟ್ಟು ಬಡ್ಡಿ ವರ್ಷಕ್ಕೆ ${fmtINR(grossInt)}, ಆದರೆ ${v.slab}% ಸ್ಲ್ಯಾಬ್‌ನಲ್ಲಿ ${fmtINR(taxPaid)} ತೆರಿಗೆ ಕಟ್ ಆಗಿ ಕೈಗೆ ಸಿಗುವುದು ${fmtINR(netInt)} ಮಾತ್ರ (${netYield}% ನಿವ್ವಳ ಬಡ್ಡಿ—6% ಹಣದುಬ್ಬರಕ್ಕಿಂತ ಕಡಿಮೆ).${insNote.kn}`,
          mr: `वार्षिक व्याज ${fmtINR(grossInt)} दिसते, पण ${v.slab}% स्लॅबमध्ये ${fmtINR(taxPaid)} कर जाऊन हातात फक्त ${fmtINR(netInt)} उरतात (${netYield}% निव्वळ परतावा—६% महागाईपेक्षा कमी).${insNote.mr}`,
          te: `వార్షిక వడ్డీ ${fmtINR(grossInt)} కనిపిస్తుంది, కానీ ${v.slab}% స్లాబ్‌లో ${fmtINR(taxPaid)} పన్ను పోను చేతికి వచ్చేది ${fmtINR(netInt)} మాత్రమే (${netYield}% నికర రాబడి—6% ద్రవ్యోల్బణం కంటే తక్కువ).${insNote.te}`,
          ta: `ஆண்டு வட்டி ${fmtINR(grossInt)}, ஆனால் ${v.slab}% வரி வரம்பில் ${fmtINR(taxPaid)} வரி போக கையில் மிஞ்சுவது ${fmtINR(netInt)} மட்டுமே (${netYield}% நிகர வருமானம்—6% விலைவாசி உயர்வை விடக் குறைவு).${insNote.ta}`,
          hi: `सालाना ब्याज ${fmtINR(grossInt)} है, लेकिन ${v.slab}% स्लैब में ${fmtINR(taxPaid)} टैक्स कटने के बाद हाथ में सिर्फ ${fmtINR(netInt)} बचते हैं (${netYield}% शुद्ध रिटर्न—6% महंगाई से भी कम)।${insNote.hi}`
        };
        return msgs[lang] || msgs.en;
      }
    },

    "bonds": {
      inputs: [
        { key: "amount", min: 10000, max: 100000000, step: 25000, defaultVal: 100000,
          label: { en: "Bond Investment (₹)", kn: "ಬಾಂಡ್ ಹೂಡಿಕೆ (₹)", mr: "बॉण्ड गुंतवणूक (₹)", te: "బాండ్ పెట్టుబడి (₹)", ta: "பாண்ட் முதலீடு (₹)", hi: "बॉन्ड निवेश (₹)" } },
        { key: "yield", min: 8, max: 15, step: 0.5, defaultVal: 11.0,
          label: { en: "Promised Yield (%)", kn: "ಬಾಂಡ್ ಬಡ್ಡಿ ದರ (%)", mr: "बॉण्ड व्याजदर (%)", te: "బాండ్ వడ్డీ (%)", ta: "பாண்ட் வட்டி (%)", hi: "बॉन्ड ब्याज दर (%)" } },
        { key: "slab", min: 0, max: 30, step: 5, defaultVal: 30,
          label: { en: "Tax Slab (%)", kn: "ತೆರಿಗೆ ಸ್ಲ್ಯಾಬ್ (%)", mr: "टॅक्स स्लॅब (%)", te: "ట్యాక్స్ స్లాబ్ (%)", ta: "வரி வரம்பு (%)", hi: "टैक्स स्लैब (%)" } }
      ],
      compute: function(v, lang) {
        const effTax = (v.slab * 1.04) / 100;
        const bondNet = v.amount * (v.yield / 100) * (1 - effTax);
        const fdNet = v.amount * 0.07 * (1 - effTax);
        const extra = Math.max(0, bondNet - fdNet);
        const msgs = {
          en: `After ${v.slab}% tax, an ${v.yield}% NBFC bond pays ${fmtINR(bondNet)}/yr vs ${fmtINR(fdNet)}/yr in a safe 7% Bank FD. You are risking 100% of your ${fmtINR(v.amount)} principal (with ₹0 DICGC insurance) just to earn an extra ${fmtINR(extra)}/yr.`,
          kn: `${v.slab}% ತೆರಿಗೆಯ ನಂತರ, ${v.yield}% ಬಾಂಡ್ ವರ್ಷಕ್ಕೆ ${fmtINR(bondNet)} ನೀಡಿದರೆ ಸುರಕ್ಷಿತ 7% ಬ್ಯಾಂಕ್ FD ${fmtINR(fdNet)} ನೀಡುತ್ತದೆ. ಕೇವಲ ${fmtINR(extra)} ಹೆಚ್ಚುವರಿ ಬಡ್ಡಿಗಾಗಿ ನಿಮ್ಮ ಸಂಪೂರ್ಣ ${fmtINR(v.amount)} ಅಸಲನ್ನು (₹0 ವಿಮೆ) ಅಪಾಯಕ್ಕೆ ಒಡ್ಡುತ್ತಿದ್ದೀರಿ.`,
          mr: `${v.slab}% करानंतर, ${v.yield}% बॉण्डमध्ये वर्षाला ${fmtINR(bondNet)} मिळतात तर सुरक्षित ७% बँक FD मध्ये ${fmtINR(fdNet)}. वर्षाला केवळ ${fmtINR(extra)} जास्त मिळवण्यासाठी तुम्ही तुमचे संपूर्ण ${fmtINR(v.amount)} मुद्दल (₹० विमा) धोक्यात घालत आहात.`,
          te: `${v.slab}% పన్ను తర్వాత, ${v.yield}% బాండ్ ఏడాదికి ${fmtINR(bondNet)} ఇస్తే సురక్షితమైన 7% బ్యాంకు FD ${fmtINR(fdNet)} ఇస్తుంది. ఏడాదికి కేవలం ${fmtINR(extra)} అదనపు వడ్డీ కోసం మీ మొత్తం ${fmtINR(v.amount)} అసలును (₹0 బీమా) రిస్క్‌లో పెడుతున్నారు.`,
          ta: `${v.slab}% வரிக்குப் பின், ${v.yield}% பாண்ட் ஆண்டுக்கு ${fmtINR(bondNet)} தரும்; பாதுகாப்பான 7% வங்கி FD ${fmtINR(fdNet)} தரும். வெறும் ${fmtINR(extra)} கூடுதல் வட்டிக்காக உங்கள் முழு ${fmtINR(v.amount)} அசலையும் (₹0 காப்பீடு) ஆபத்தில் வைக்கிறீர்கள்.`,
          hi: `${v.slab}% टैक्स के बाद, ${v.yield}% बॉन्ड से सालाना ${fmtINR(bondNet)} मिलते हैं जबकि सुरक्षित 7% बैंक FD से ${fmtINR(fdNet)}। सालाना सिर्फ ${fmtINR(extra)} अतिरिक्त कमाने के लिए आप अपना पूरा ${fmtINR(v.amount)} मूलधन (₹0 बीमा) जोखिम में डाल रहे हैं।`
        };
        return msgs[lang] || msgs.en;
      }
    },

    "nps-epf": {
      inputs: [
        { key: "corpus", min: 100000, max: 500000000, step: 100000, defaultVal: 1000000,
          label: { en: "NPS Corpus at 60 (₹)", kn: "60ನೇ ವಯಸ್ಸಿಗೆ NPS ನಿಧಿ (₹)", mr: "वय ६० ला NPS निधी (₹)", te: "60 ఏళ్లకు NPS నిధి (₹)", ta: "60 வயதில் NPS நிதி (₹)", hi: "उम्र 60 पर NPS फंड (₹)" } },
        { key: "annuityRate", min: 4, max: 8, step: 0.25, defaultVal: 6.0,
          label: { en: "Annuity Rate (%)", kn: "ಪೆನ್ಷನ್ ದರ (%)", mr: "पेन्शन दर (%)", te: "పెన్షన్ రేటు (%)", ta: "பென்ஷன் விகிதம் (%)", hi: "पेंशन दर (%)" } },
        { key: "slab", min: 0, max: 30, step: 5, defaultVal: 20,
          label: { en: "Retirement Tax Slab (%)", kn: "ನಿವೃತ್ತಿ ತೆರಿಗೆ ಸ್ಲ್ಯಾಬ್ (%)", mr: "निवृत्ती टॅक्स स्लॅब (%)", te: "రిటైర్మెంట్ ట్యాక్స్ స్లాబ్ (%)", ta: "ஓய்வுக்கால வரி (%)", hi: "रिटायरमेंट टैक्स स्लैब (%)" } }
      ],
      compute: function(v, lang) {
        const lumpSum = v.corpus * 0.60;
        const lockedAnnuity = v.corpus * 0.40;
        const effTax = (v.slab * 1.04) / 100;
        const monthlyGross = (lockedAnnuity * (v.annuityRate / 100)) / 12;
        const monthlyNet = monthlyGross * (1 - effTax);
        const msgs = {
          en: `At age 60: ${fmtINR(lumpSum)} (60%) is tax-free lump sum, while ${fmtINR(lockedAnnuity)} (40%) is permanently locked into an insurance annuity paying ${fmtINR(monthlyNet)}/month after ${v.slab}% tax.`,
          kn: `60ನೇ ವಯಸ್ಸಿನಲ್ಲಿ: ${fmtINR(lumpSum)} (60%) ತೆರಿಗೆ ಮುಕ್ತವಾಗಿ ಕೈಗೆ ಸಿಗುತ್ತದೆ; ಆದರೆ ${fmtINR(lockedAnnuity)} (40%) ಕಡ್ಡಾಯವಾಗಿ ಪೆನ್ಷನ್ ಪ್ಲಾನ್‌ನಲ್ಲಿ ಲಾಕ್ ಆಗಿ, ${v.slab}% ತೆರಿಗೆಯ ನಂತರ ತಿಂಗಳಿಗೆ ${fmtINR(monthlyNet)} ಪೆನ್ಷನ್ ಬರುತ್ತದೆ.`,
          mr: `वयाच्या ६० व्या वर्षी: ${fmtINR(lumpSum)} (६०%) रक्कम करमुक्त मिळते, तर ${fmtINR(lockedAnnuity)} (४०%) रक्कम पेन्शन प्लॅनमध्ये कायमची अडकते—ज्यातून ${v.slab}% करानंतर दरमहा ${fmtINR(monthlyNet)} पेन्शन मिळते.`,
          te: `60 ఏళ్ల వయసులో: ${fmtINR(lumpSum)} (60%) పన్ను లేకుండా చేతికి వస్తుంది, కానీ ${fmtINR(lockedAnnuity)} (40%) ఖచ్చితంగా పెన్షన్ ప్లాన్‌లో లాక్ చేయబడి ${v.slab}% పన్ను తర్వాత నెలకు ${fmtINR(monthlyNet)} పెన్షన్ ఇస్తుంది.`,
          ta: `60 வயதில்: ${fmtINR(lumpSum)} (60%) வரி இல்லாமல் கிடைக்கும்; ஆனால் ${fmtINR(lockedAnnuity)} (40%) கட்டாய பென்ஷன் திட்டத்தில் முடக்கப்பட்டு ${v.slab}% வரிக்குப் பின் மாதம் ${fmtINR(monthlyNet)} பென்ஷன் தரும்.`,
          hi: `60 की उम्र में: ${fmtINR(lumpSum)} (60%) टैक्स-फ्री एकमुश्त मिलता है, जबकि ${fmtINR(lockedAnnuity)} (40%) अनिवार्य रूप से पेंशन प्लान में लॉक हो जाता है जिससे ${v.slab}% टैक्स के बाद महीने के ${fmtINR(monthlyNet)} मिलते हैं।`
        };
        return msgs[lang] || msgs.en;
      }
    },

    "reits": {
      inputs: [
        { key: "amount", min: 5000, max: 100000000, step: 25000, defaultVal: 100000,
          label: { en: "Investment (₹)", kn: "ಹೂಡಿಕೆ ಮೊತ್ತ (₹)", mr: "गुंतवणूक (₹)", te: "పెట్టుబడి (₹)", ta: "முதலீடு (₹)", hi: "निवेश राशि (₹)" } },
        { key: "distYield", min: 5, max: 11, step: 0.25, defaultVal: 7.5,
          label: { en: "Headline Yield (%)", kn: "ತೋರಿಸುವ ಆದಾಯ (%)", mr: "दर्शनी परतावा (%)", te: "చూపించే రాబడి (%)", ta: "காட்டப்படும் வருமானம் (%)", hi: "दिखाया गया रिटर्न (%)" } },
        { key: "slab", min: 0, max: 30, step: 5, defaultVal: 30,
          label: { en: "Tax Slab (%)", kn: "ತೆರಿಗೆ ಸ್ಲ್ಯಾಬ್ (%)", mr: "टॅक्स स्लॅब (%)", te: "ట్యాక్స్ స్లాబ్ (%)", ta: "வரி வரம்பு (%)", hi: "टैक्स स्लैब (%)" } }
      ],
      compute: function(v, lang) {
        const grossCash = v.amount * (v.distYield / 100);
        // ~70% of REIT payout is interest taxed at slab
        const interestPart = grossCash * 0.70;
        const effTax = (v.slab * 1.04) / 100;
        const tax = interestPart * effTax;
        const netCash = grossCash - tax;
        const netYield = ((netCash / v.amount) * 100).toFixed(2);
        const msgs = {
          en: `Gross payout is ${fmtINR(grossCash)}/yr (${v.distYield}%), but since ~70% is interest taxed at your ${v.slab}% slab (${fmtINR(tax)} tax), you keep ${fmtINR(netCash)}/yr (${netYield}% net yield)—plus you must split it into 3 schedules in your ITR.`,
          kn: `ಒಟ್ಟು ಆದಾಯ ವರ್ಷಕ್ಕೆ ${fmtINR(grossCash)} (${v.distYield}%), ಆದರೆ ಇದರ ~70% ಬಡ್ಡಿಯಾಗಿರುವುದರಿಂದ ${v.slab}% ಸ್ಲ್ಯಾಬ್ ಪ್ರಕಾರ ${fmtINR(tax)} ತೆರಿಗೆ ಕಟ್ ಆಗಿ ಕೈಗೆ ಸಿಗುವುದು ${fmtINR(netCash)} ಮಾತ್ರ (${netYield}% ನಿವ್ವಳ ಆದಾಯ).`,
          mr: `एकूण परतावा वर्षाला ${fmtINR(grossCash)} (${v.distYield}%) दिसतो, पण त्यातील ~७०% भाग व्याजाचा असल्याने ${v.slab}% स्लॅबनुसार ${fmtINR(tax)} कर जाऊन हातात ${fmtINR(netCash)} उरतात (${netYield}% निव्वळ परतावा).`,
          te: `స్థూల ఆదాయం ఏడాదికి ${fmtINR(grossCash)} (${v.distYield}%), కానీ అందులో ~70% వడ్డీ కాబట్టి మీ ${v.slab}% స్లాబ్ ప్రకారం ${fmtINR(tax)} పన్ను పోను చేతికి వచ్చేది ${fmtINR(netCash)} మాత్రమే (${netYield}% నికర రాబడి).`,
          ta: `மொத்த வருமானம் ஆண்டுக்கு ${fmtINR(grossCash)} (${v.distYield}%), ஆனால் அதில் ~70% வட்டி என்பதால் ${v.slab}% வரி வரம்பின்படி ${fmtINR(tax)} வரி போக மிஞ்சுவது ${fmtINR(netCash)} மட்டுமே (${netYield}% நிகர வருமானம்).`,
          hi: `कुल सालाना आय ${fmtINR(grossCash)} (${v.distYield}%) दिखती है, लेकिन ~70% हिस्सा ब्याज होने के कारण ${v.slab}% स्लैब पर ${fmtINR(tax)} टैक्स कटकर हाथ में ${fmtINR(netCash)} बचते हैं (${netYield}% शुद्ध रिटर्न)।`
        };
        return msgs[lang] || msgs.en;
      }
    },

    "gold": {
      inputs: [
        { key: "amount", min: 5000, max: 100000000, step: 10000, defaultVal: 100000,
          label: { en: "Spent on Jewellery (₹)", kn: "ಆಭರಣಕ್ಕೆ ಕೊಟ್ಟ ಹಣ (₹)", mr: "दागिन्यांवर खर्च (₹)", te: "నగలపై ఖర్చు (₹)", ta: "நகைக்கு கொடுத்த பணம் (₹)", hi: "गहनों पर खर्च (₹)" } },
        { key: "making", min: 0, max: 30, step: 1, defaultVal: 15,
          label: { en: "Making Charges (%)", kn: "ಮೇಕಿಂಗ್ ಚಾರ್ಜ್ (%)", mr: "घडणावळ (%)", te: "తరుగు/మజూరీ (%)", ta: "செய்கூலி & சேதாரம் (%)", hi: "मेकिंग चार्ज (%)" } }
      ],
      compute: function(v, lang) {
        // Total bill = goldValue * (1 + making/100) * 1.03 (3% GST)
        const goldVal = v.amount / ((1 + v.making / 100) * 1.03);
        const lostDay1 = Math.max(0, v.amount - goldVal);
        const etfVal = v.amount * 0.998; // ~0.2% brokerage/impact
        const msgs = {
          en: `Out of ${fmtINR(v.amount)} paid at the jeweller (${v.making}% making + 3% GST), you get only ${fmtINR(goldVal)} of actual gold—${fmtINR(lostDay1)} is lost on Day 1. The same ${fmtINR(v.amount)} in a Gold ETF holds ${fmtINR(etfVal)} of 99.5% pure gold.`,
          kn: `ಆಭರಣ ಅಂಗಡಿಯಲ್ಲಿ ಕೊಟ್ಟ ${fmtINR(v.amount)} ರಲ್ಲಿ (${v.making}% ಮೇಕಿಂಗ್ + 3% GST), ನಿಮಗೆ ಸಿಗುವ ನಿಜವಾದ ಚಿನ್ನ ಕೇವಲ ${fmtINR(goldVal)}—ಮೊದಲ ದಿನವೇ ${fmtINR(lostDay1)} ನಷ್ಟವಾಗುತ್ತದೆ. ಅದೇ Gold ETF ನಲ್ಲಿ ${fmtINR(etfVal)} ಮೌಲ್ಯದ ಶುದ್ಧ ಚಿನ್ನ ಸಿಗುತ್ತದೆ.`,
          mr: `सोनाराकडे दिलेल्या ${fmtINR(v.amount)} पैकी (${v.making}% घडणावळ + ३% GST), तुम्हाला प्रत्यक्षात फक्त ${fmtINR(goldVal)} चेच सोने मिळते—पहिल्याच दिवशी ${fmtINR(lostDay1)} जातात. Gold ETF मध्ये ${fmtINR(etfVal)} चे शुद्ध सोने मिळते.`,
          te: `నగల దుకాణంలో చెల్లించిన ${fmtINR(v.amount)} లో (${v.making}% తరుగు/మజూరీ + 3% GST), మీకు వచ్చే అసలు బంగారం విలువ కేవలం ${fmtINR(goldVal)} మాత్రమే—మೊదటి రోజే ${fmtINR(lostDay1)} పోతుంది. అదే Gold ETF లో ${fmtINR(etfVal)} విలువైన బంగారం ఉంటుంది.`,
          ta: `நகைக்கடையில் கொடுத்த ${fmtINR(v.amount)} தொகையில் (${v.making}% செய்கூலி + 3% GST), உங்களுக்குக் கிடைக்கும் உண்மையான தங்கம் வெறும் ${fmtINR(goldVal)} மட்டுமே—முதல் நாளே ${fmtINR(lostDay1)} இழப்பு. Gold ETF இல் ${fmtINR(etfVal)} மதிப்புள்ள தங்கம் கிடைக்கும்.`,
          hi: `ज्वेलर को दिए गए ${fmtINR(v.amount)} में से (${v.making}% मेकिंग चार्ज + 3% GST), आपको वास्तव में सिर्फ ${fmtINR(goldVal)} का सोना मिलता है—पहले ही दिन ${fmtINR(lostDay1)} का नुकसान। वहीं Gold ETF में ${fmtINR(etfVal)} का शुद्ध सोना मिलता है।`
        };
        return msgs[lang] || msgs.en;
      }
    },

    "digital-gold": {
      inputs: [
        { key: "amount", min: 500, max: 10000000, step: 5000, defaultVal: 100000,
          label: { en: "Amount Paid on App (₹)", kn: "ಆಪ್‌ನಲ್ಲಿ ಕೊಟ್ಟ ಹಣ (₹)", mr: "ॲपवर दिलेली रक्कम (₹)", te: "యాప్‌లో చెల్లించిన మొత్తం (₹)", ta: "செயலியில் கொடுத்த பணம் (₹)", hi: "ऐप पर दी गई राशि (₹)" } },
        { key: "spread", min: 1, max: 6, step: 0.5, defaultVal: 3.0,
          label: { en: "Buy-Sell Price Spread (%)", kn: "ಖರೀದಿ-ಮಾರಾಟ ಬೆಲೆ ವ್ಯತ್ಯಾಸ (%)", mr: "खरेदी-विक्री भाव फरक (%)", te: "కొనుగోలు-అమ్మకం ధర తేడా (%)", ta: "வாங்கும்-விற்கும் விலை வித்தியாசம் (%)", hi: "खरीद-बिक्री भाव अंतर (%)" } }
      ],
      compute: function(v, lang) {
        const afterGst = v.amount / 1.03;
        const sellVal = afterGst * (1 - v.spread / 100);
        const lost = Math.max(0, v.amount - sellVal);
        const pct = ((lost / v.amount) * 100).toFixed(1);
        const msgs = {
          en: `Pay ${fmtINR(v.amount)} on the app: 3% GST + ${v.spread}% buy-sell spread immediately cuts your resale value to ${fmtINR(sellVal)}—an instant Day-1 loss of ${fmtINR(lost)} (${pct}%) in an unregulated product.`,
          kn: `ಆಪ್‌ನಲ್ಲಿ ${fmtINR(v.amount)} ಕೊಟ್ಟು ಖರೀದಿಸಿದ ತಕ್ಷಣ 3% GST + ${v.spread}% ಬೆಲೆ ವ್ಯತ್ಯಾಸದಿಂದ ನಿಮ್ಮ ಮರುಮಾರಾಟ ಮೌಲ್ಯ ${fmtINR(sellVal)} ಗೆ ಇಳಿಯುತ್ತದೆ—ಮೊದಲ ನಿಮಿಷದಲ್ಲೇ ${fmtINR(lost)} (${pct}%) ನೇರ ನಷ್ಟ.`,
          mr: `ॲपवर ${fmtINR(v.amount)} देऊन खरेदी करताच ३% GST + ${v.spread}% भाव फरकामुळे तुमचे विक्री मूल्य लगेच ${fmtINR(sellVal)} वर येते—पहिल्याच मिनिटाला ${fmtINR(lost)} (${pct}%) थेट तोटा.`,
          te: `యాప్‌లో ${fmtINR(v.amount)} పెట్టి కొనగానే 3% GST + ${v.spread}% ధర తేడా వల్ల మీ అమ్మకం విలువ వెంటనే ${fmtINR(sellVal)} కు పడిపోతుంది—మొదటి నిమిషంలోనే ${fmtINR(lost)} (${pct}%) ప్రత్యక్ష నష్టం.`,
          ta: `செயலியில் ${fmtINR(v.amount)} கொடுத்து வாங்கிய உடனேயே 3% GST + ${v.spread}% விலை வித்தியாசத்தால் உங்கள் விற்பனை மதிப்பு ${fmtINR(sellVal)} ஆகக் குறைகிறது—முதல் நிமிடத்திலேயே ${fmtINR(lost)} (${pct}%) இழப்பு.`,
          hi: `ऐप पर ${fmtINR(v.amount)} लगाते ही 3% GST + ${v.spread}% भाव अंतर के कारण आपका रीसेल मूल्य तुरंत घटकर ${fmtINR(sellVal)} रह जाता है—पहले ही मिनट में ${fmtINR(lost)} (${pct}%) का सीधा नुकसान।`
        };
        return msgs[lang] || msgs.en;
      }
    },

    "ulip": {
      inputs: [
        { key: "premium", min: 10000, max: 10000000, step: 25000, defaultVal: 100000,
          label: { en: "Annual Premium (₹/yr)", kn: "ವಾರ್ಷಿಕ ಪ್ರೀಮಿಯಂ (₹)", mr: "वार्षिक प्रीमियम (₹)", te: "వార్షిక ప్రీమియం (₹)", ta: "ஆண்டு பிரீமியம் (₹)", hi: "सालाना प्रीमियम (₹)" } },
        { key: "payYears", min: 5, max: 30, step: 1, defaultVal: 10,
          label: { en: "Pay For (Years)", kn: "ಕಟ್ಟುವ ವರ್ಷಗಳು", mr: "प्रीमियम भरणे (वर्षे)", te: "కట్టే ఏళ్లు", ta: "கட்டும் ஆண்டுகள்", hi: "भुगतान अवधि (वर्ष)" } },
        { key: "matYears", min: 5, max: 40, step: 1, defaultVal: 20,
          label: { en: "Maturity At (Year)", kn: "ಮೆಚ್ಯೂರಿಟಿ ವರ್ಷ", mr: "मॅच्युरिटी वर्ष", te: "మెచ్యూరిటీ ఏడాది", ta: "முதிர்வு ஆண்டு", hi: "मैच्योरिटी वर्ष" } },
        { key: "payout", min: 50000, max: 500000000, step: 100000, defaultVal: 2200000,
          label: { en: "Promised Payout (₹)", kn: "ಭರವಸೆ ನೀಡಿದ ಮೊತ್ತ (₹)", mr: "मिळणारी रक्कम (₹)", te: "చెప్పిన మెచ్యూరిటీ (₹)", ta: "வாக்குறுதி தொகை (₹)", hi: "वादा की गई रकम (₹)" } }
      ],
      compute: function(v, lang) {
        const matY = Math.max(v.payYears, v.matYears);
        const totalPaid = v.premium * v.payYears;
        const xirr = computeEndowmentXIRR(v.premium, v.payYears, matY, v.payout).toFixed(2);
        const indexCorpus = computeIndexCorpus(v.premium, v.payYears, matY, 0.12);
        const diff = Math.max(0, indexCorpus - v.payout);
        const msgs = {
          en: `Paying ${fmtINR(v.premium)}/yr for ${v.payYears} yrs (${fmtINR(totalPaid)} total) to get ${fmtINR(v.payout)} at Year ${matY} is a true XIRR of just ${xirr}% p.a. The exact same cashflow in a Nifty 50 Index Fund (12% CAGR) grows to ${fmtINR(indexCorpus)}—costing you ${fmtINR(diff)} in lost wealth.`,
          kn: `${v.payYears} ವರ್ಷಗಳ ಕಾಲ ವಾರ್ಷಿಕ ${fmtINR(v.premium)} ಕಟ್ಟಿ (ಒಟ್ಟು ${fmtINR(totalPaid)}) ${matY}ನೇ ವರ್ಷದಲ್ಲಿ ${fmtINR(v.payout)} ಪಡೆಯುವುದರ ನಿಜವಾದ ವಾರ್ಷಿಕ ಬಡ್ಡಿ (XIRR) ಕೇವಲ ${xirr}% ಮಾತ್ರ! ಇದೇ ಹಣವನ್ನು Nifty 50 Index Fund ನಲ್ಲಿ (12% CAGR) ಹಾಕಿದರೆ ${fmtINR(indexCorpus)} ಆಗುತ್ತದೆ—ನಿಮಗೆ ${fmtINR(diff)} ನಷ್ಟ.`,
          mr: `${v.payYears} वर्षे दरवर्षी ${fmtINR(v.premium)} भरून (एकूण ${fmtINR(totalPaid)}) ${matY} व्या वर्षी ${fmtINR(v.payout)} मिळणे म्हणजे खरा वार्षिक परतावा (XIRR) फक्त ${xirr}% आहे! हाच पैसा Nifty 50 Index Fund (१२% CAGR) मध्ये गुंतवल्यास ${fmtINR(indexCorpus)} होतात—तुमचे ${fmtINR(diff)} नुकसान होते.`,
          te: `${v.payYears} ఏళ్ల పాటు ఏటా ${fmtINR(v.premium)} కట్టి (మొత్తం ${fmtINR(totalPaid)}) ${matY}వ ఏట ${fmtINR(v.payout)} పొందడం అంటే నిజమైన వార్షిక రాబడి (XIRR) కేవలం ${xirr}% మాత్రమే! ఇదే డబ్బును Nifty 50 Index Fund (12% CAGR) లో పెడితే ${fmtINR(indexCorpus)} అవుతుంది—మీకు ${fmtINR(diff)} సంపద నష్టం.`,
          ta: `${v.payYears} ஆண்டுகளுக்கு ஆண்டுதோறும் ${fmtINR(v.premium)} கட்டி (மொத்தம் ${fmtINR(totalPaid)}) ${matY}-வது ஆண்டில் ${fmtINR(v.payout)} பெறுவதன் உண்மையான ஆண்டு வருமானம் (XIRR) வெறும் ${xirr}% மட்டுமே! இதே பணத்தை Nifty 50 Index Fund (12% CAGR) இல் முதலீடு செய்தால் ${fmtINR(indexCorpus)} கிடைக்கும்—உங்களுக்கு ${fmtINR(diff)} இழப்பு.`,
          hi: `${v.payYears} साल तक सालाना ${fmtINR(v.premium)} भरकर (कुल ${fmtINR(totalPaid)}) ${matY}वें साल में ${fmtINR(v.payout)} पाना असल में सिर्फ ${xirr}% सालाना रिटर्न (XIRR) है! यही पैसा Nifty 50 Index Fund (12% CAGR) में लगाने पर ${fmtINR(indexCorpus)} बनता है—आपको ${fmtINR(diff)} का नुकसान होता है।`
        };
        return msgs[lang] || msgs.en;
      }
    },

    "fno": {
      inputs: [
        { key: "capital", min: 10000, max: 100000000, step: 25000, defaultVal: 100000,
          label: { en: "Trading Capital (₹)", kn: "ಟ್ರೇಡಿಂಗ್ ಬಂಡವಾಳ (₹)", mr: "ट्रेडिंग भांडवल (₹)", te: "ట్రేడింగ్ పెట్టుబడి (₹)", ta: "டிரேடிங் முதலீடு (₹)", hi: "ट्रेडिंग पूंजी (₹)" } },
        { key: "tradesPerWeek", min: 1, max: 200, step: 5, defaultVal: 10,
          label: { en: "Trades / Week", kn: "ವಾರದ ಟ್ರೇಡ್‌ಗಳು", mr: "आठवड्याचे ट्रेड्स", te: "వారానికి ట్రేడ్లు", ta: "வார வர்த்தகங்கள்", hi: "साप्ताहिक ट्रेड्स" } },
        { key: "costPerTrade", min: 40, max: 1000, step: 20, defaultVal: 120,
          label: { en: "Brokerage + STT / Trade (₹)", kn: "ಪ್ರತಿ ಟ್ರೇಡ್ ವೆಚ್ಚ (₹)", mr: "प्रती ट्रेड खर्च (₹)", te: "ప్రతి ట్రేడ్ ఖర్చు (₹)", ta: "ஒரு டிரேட் செலவு (₹)", hi: "प्रति ट्रेड खर्च (₹)" } }
      ],
      compute: function(v, lang) {
        const annualCost = v.tradesPerWeek * 52 * v.costPerTrade;
        const pctBurn = ((annualCost / v.capital) * 100).toFixed(1);
        const msgs = {
          en: `${v.tradesPerWeek} trades/week at ${fmtINR(v.costPerTrade)} per round-trip burns ${fmtINR(annualCost)}/year in brokerage, hiked STT, and exchange fees alone—wiping out ${pctBurn}% of your ${fmtINR(v.capital)} capital before you make ₹1 of profit.`,
          kn: `ವಾರಕ್ಕೆ ${v.tradesPerWeek} ಟ್ರೇಡ್‌ಗಳಂತೆ ಪ್ರತಿ ಟ್ರೇಡ್‌ಗೆ ${fmtINR(v.costPerTrade)} ವೆಚ್ಚವಾದರೆ ವರ್ಷಕ್ಕೆ ${fmtINR(annualCost)} ಕೇವಲ ಬ್ರೋಕರೇಜ್ ಮತ್ತು STT ತೆರಿಗೆಯಲ್ಲೇ ಕರಗಿಹೋಗುತ್ತದೆ—ನಿಮ್ಮ ${fmtINR(v.capital)} ಬಂಡವಾಳದ ${pctBurn}% ಭಾಗ ಶುಲ್ಕದಲ್ಲೇ ಖಾಲಿಯಾಗುತ್ತದೆ.`,
          mr: `आठवड्याला ${v.tradesPerWeek} ट्रेड्स आणि प्रती ट्रेड ${fmtINR(v.costPerTrade)} खर्च धरल्यास वर्षाला ${fmtINR(annualCost)} केवळ ब्रोकरेज आणि STT करातच जातात—₹१ नफा कमावण्याआधीच तुमच्या ${fmtINR(v.capital)} भांडवलातील ${pctBurn}% रक्कम शुल्कात संपते.`,
          te: `వారానికి ${v.tradesPerWeek} ట్రేడ్లు, ప్రతి ట్రేడ్‌కు ${fmtINR(v.costPerTrade)} ఖర్చుతో ఏడాదికి ${fmtINR(annualCost)} కేవలం బ్రోకరేజ్ మరియు STT పన్నులకే పోతుంది—₹1 లాభం రాకముందే మీ ${fmtINR(v.capital)} పెట్టుబడిలో ${pctBurn}% ఛార్జీలకే ఆవిరవుతుంది.`,
          ta: `வாரத்திற்கு ${v.tradesPerWeek} டிரேடுகள், ஒரு டிரேடுக்கு ${fmtINR(v.costPerTrade)} செலவு என்றால் ஆண்டுக்கு ${fmtINR(annualCost)} வெறும் ப்ரோக்கரேஜ் மற்றும் STT வரிக்கே போய்விடும்—₹1 லாபம் ஈட்டும் முன்பே உங்கள் ${fmtINR(v.capital)} முதலீட்டில் ${pctBurn}% கரைந்துவிடும்.`,
          hi: `सप्ताह में ${v.tradesPerWeek} ट्रेड्स और प्रति ट्रेड ${fmtINR(v.costPerTrade)} खर्च के हिसाब से सालाना ${fmtINR(annualCost)} सिर्फ ब्रोकरेज और STT टैक्स में जल जाते हैं—₹1 मुनाफा कमाने से पहले ही आपकी ${fmtINR(v.capital)} पूंजी का ${pctBurn}% हिस्सा फीस में खत्म हो जाता है।`
        };
        return msgs[lang] || msgs.en;
      }
    },

    "crypto": {
      inputs: [
        { key: "profit", min: 0, max: 100000000, step: 10000, defaultVal: 100000,
          label: { en: "Profit on Coin A (₹)", kn: "ಕಾಯಿನ್ A ಲಾಭ (₹)", mr: "कॉइन A वरील नफा (₹)", te: "కాయిన్ A లాభం (₹)", ta: "காயின் A லாபம் (₹)", hi: "कॉइन A पर मुनाफा (₹)" } },
        { key: "loss", min: 0, max: 100000000, step: 10000, defaultVal: 100000,
          label: { en: "Loss on Coin B (₹)", kn: "ಕಾಯಿನ್ B ನಷ್ಟ (₹)", mr: "कॉइन B वरील तोटा (₹)", te: "కాయిన్ B నష్టం (₹)", ta: "காயின் B நஷ்டம் (₹)", hi: "कॉइन B पर घाटा (₹)" } }
      ],
      compute: function(v, lang) {
        const netReal = v.profit - v.loss;
        const tax = Math.round(v.profit * 0.312); // Sec 115BBH: 0% loss offset allowed!
        const takeHome = netReal - tax;
        const msgs = {
          en: `Your real net gain is ${fmtINR(netReal)}, but because Sec 115BBH bans loss set-off, you still owe 31.2% tax on Coin A's profit = ${fmtINR(tax)}. Your net outcome after tax is ${fmtINR(takeHome)}.`,
          kn: `ನಿಮ್ಮ ನಿಜವಾದ ನಿವ್ವಳ ಲಾಭ ${fmtINR(netReal)}, ಆದರೆ Sec 115BBH ಪ್ರಕಾರ ನಷ್ಟವನ್ನು ಹೊಂದಾಣಿಕೆ ಮಾಡಲು ಅವಕಾಶವಿಲ್ಲದ ಕಾರಣ ಕಾಯಿನ್ A ಲಾಭದ ಮೇಲೆ 31.2% ತೆರಿಗೆ = ${fmtINR(tax)} ಕಟ್ಟಲೇಬೇಕು! ತೆರಿಗೆಯ ನಂತರ ನಿಮ್ಮ ನಿವ್ವಳ ಫಲಿತಾಂಶ: ${fmtINR(takeHome)}.`,
          mr: `तुमचा खरा निव्वळ नफा ${fmtINR(netReal)} आहे, पण कलम 115BBH नुसार तोटा वजा करता येत नसल्याने कॉइन A च्या नफ्यावर ३१.२% कर = ${fmtINR(tax)} भरावाच लागतो! करानंतर तुमच्या हातात ${fmtINR(takeHome)} उरतात.`,
          te: `మీ నిజమైన నికర లాభం ${fmtINR(netReal)}, కానీ Sec 115BBH ప్రకారం నష్టాన్ని తగ్గించుకునే వీలు లేనందున కాయిన్ A లాభంపై 31.2% పన్ను = ${fmtINR(tax)} కట్టాల్సిందే! పన్ను తర్వాత మీ నికర ఫలితం: ${fmtINR(takeHome)}.`,
          ta: `உங்கள் உண்மையான நிகர லாபம் ${fmtINR(netReal)}, ஆனால் பிரிவு 115BBH படி நஷ்டத்தைக் கழிக்க அனுமதி இல்லாததால் காயின் A லாபத்திற்கு 31.2% வரி = ${fmtINR(tax)} கட்டியாக வேண்டும்! வரிக்குப் பின் உங்கள் நிகர முடிவு: ${fmtINR(takeHome)}.`,
          hi: `आपका असली शुद्ध मुनाफा ${fmtINR(netReal)} है, लेकिन सेक्शन 115BBH के तहत घाटा घटाने की अनुमति न होने के कारण आपको कॉइन A के मुनाफे पर 31.2% टैक्स = ${fmtINR(tax)} देना ही होगा! टैक्स के बाद आपका शुद्ध परिणाम: ${fmtINR(takeHome)}।`
        };
        return msgs[lang] || msgs.en;
      }
    }
  };
})();

// Ensure "equity" ID in index.html maps to "direct-equity"
(function() {
  ["kn", "mr", "te", "ta", "hi"].forEach(function(l) {
    if (window.I18N.products[l] && window.I18N.products[l]["direct-equity"]) {
      window.I18N.products[l]["equity"] = window.I18N.products[l]["direct-equity"];
    }
  });
  if (window.I18N.calculators && window.I18N.calculators["direct-equity"]) {
    window.I18N.calculators["equity"] = window.I18N.calculators["direct-equity"];
  }
})();
